    def _validate_keyframes(
        self,
        expectations: list[Any],
        project: Mapping[str, Any],
        actual_objects: list[Any],
        *,
        tolerance: float,
    ) -> None:
        for item in expectations:
            if not isinstance(item, Mapping):
                continue
            object_name = str(item.get("object") or item.get("name") or "").strip()
            assert object_name, "keyframe expectation missing object"
            frame = int(item.get("frame"))
            obj = self._object_by_name(actual_objects, object_name)
            assert obj is not None, f"missing keyframed object: {object_name}"
            keyframe = self._find_keyframe(project, obj, object_name=object_name, frame=frame)
            assert keyframe is not None, f"{object_name} missing keyframe at frame {frame}"
            for key in ("location", "rotation", "scale"):
                if key in item:
                    self._assert_close_vector(
                        f"{object_name}.keyframe[{frame}].{key}",
                        list(item.get(key) or []),
                        list(keyframe.get(key) or []),
                        tolerance=tolerance,
                    )
            if "channels" in item:
                expected_channels = {str(channel).strip().lower() for channel in item.get("channels") or []}
                actual_channels = {
                    str(channel).strip().lower()
                    for channel in (
                        keyframe.get("channels")
                        or keyframe.get("properties")
                        or keyframe.get("paths")
                        or []
                    )
                }
                if not actual_channels:
                    actual_channels = {
                        key
                        for key in ("location", "rotation", "scale")
                        if key in keyframe and key in expected_channels
                    }
                missing = sorted(expected_channels - actual_channels)
                assert not missing, f"{object_name}.keyframe[{frame}] missing channels: {missing}"

    def _find_keyframe(
        self,
        project: Mapping[str, Any],
        obj: Mapping[str, Any],
        *,
        object_name: str,
        frame: int,
    ) -> dict[str, Any] | None:
        object_id = str(obj.get("id") or "")
        candidate_lists = [
            obj.get("keyframes"),
            (obj.get("animation") or {}).get("keyframes") if isinstance(obj.get("animation"), Mapping) else None,
            project.get("keyframes"),
            (project.get("animation") or {}).get("keyframes") if isinstance(project.get("animation"), Mapping) else None,
        ]
        for raw_list in candidate_lists:
            if not isinstance(raw_list, list):
                continue
            for raw_keyframe in raw_list:
                if not isinstance(raw_keyframe, Mapping):
                    continue
                keyframe = dict(raw_keyframe)
                keyframe_frame = keyframe.get("frame")
                if keyframe_frame is None or int(keyframe_frame) != frame:
                    continue
                keyframe_object = str(
                    keyframe.get("objectId")
                    or keyframe.get("object_id")
                    or keyframe.get("object")
                    or keyframe.get("name")
                    or ""
                )
                if keyframe_object and keyframe_object not in {object_id, object_name}:
                    continue
                return keyframe
        return None

    @staticmethod
    def _summarize_payload(payload: Mapping[str, Any], params: Mapping[str, Any]) -> dict[str, Any]:
        state = dict(payload.get("state") or {})
        projects = [dict(item) for item in state.get("projects") or [] if isinstance(item, Mapping)]
        project_id = str(params.get("project_id") or "")
        project_name = str(params.get("project_name") or "")
        project = {}
        for item in projects:
            if (project_id and str(item.get("id") or "") == project_id) or (
                project_name and str(item.get("name") or "") == project_name
            ):
                project = item
                break
        if not project and projects:
            current_id = str(state.get("currentProjectId") or "")
            project = next((item for item in projects if str(item.get("id") or "") == current_id), projects[0])

        expected_names = {
            str(item.get("name") or "")
            for item in (params.get("objects") or [])
            if isinstance(item, Mapping)
        }
        active_id = str(project.get("activeObjectId") or "")
        objects = []
        for item in project.get("objects") or []:
            if not isinstance(item, Mapping):
                continue
            if str(item.get("name") or "") in expected_names or str(item.get("id") or "") == active_id:
                objects.append(
                    {
                        "id": item.get("id"),
                        "name": item.get("name"),
                        "type": item.get("type"),
                        "collection": item.get("collection"),
                        "location": item.get("location"),
                        "rotation": item.get("rotation"),
                        "scale": item.get("scale"),
                        "materialId": item.get("materialId"),
                        "materialSlots": item.get("materialSlots"),
                        "modifiers": item.get("modifiers"),
                    }
                )

        materials = [
            {
                "id": item.get("id"),
                "name": item.get("name"),
                "color": item.get("color"),
                "roughness": item.get("roughness"),
                "metallic": item.get("metallic"),
            }
            for item in state.get("materials") or []
            if isinstance(item, Mapping)
        ]
        material_ids = {str(obj.get("materialId") or "") for obj in objects}
        materials = [item for item in materials if str(item.get("id") or "") in material_ids]

        return {
            "pageTitle": payload.get("pageTitle"),
            "pageUrl": payload.get("pageUrl"),
            "currentProjectId": state.get("currentProjectId"),
            "activeWorkspace": state.get("activeWorkspace"),
            "activePropertyTab": payload.get("activePropertyTab"),
            "project": {
                "id": project.get("id"),
                "name": project.get("name"),
                "path": project.get("path"),
                "activeObjectId": project.get("activeObjectId"),
                "currentFrame": project.get("currentFrame", state.get("currentFrame")),
                "renderEngine": project.get("renderEngine")
                or project.get("engine")
                or (project.get("render") or {}).get("engine")
                or state.get("renderEngine")
                or state.get("engine"),
                "output": project.get("output"),
                "render": project.get("render"),
                "layers": project.get("layers") or project.get("viewLayer"),
                "objects": objects,
            },
            "materials": materials,
        }
